  Definition W1 (ff fp : Z) : list (Z * Z) :=
    [(spz - 8192, spz); (as_FSB H, as_FSB H + AFS_FLAGS); (fp, fp + 1); (ff, ff + 256); (sh ff, sh ff + 32)].

  Lemma new_frame : forall m ff fp, as_RFS H ((2, ff, fp) :: LF) m ->
    fresh_frame H LF 2 ff fp
